static const int kDrumKitCount = 37;

// Drum-voice name for (kit bank/program, note), or nullptr if the note
// carries no drum or the kit is unknown. pgm is 1-based (= prg0 + 1).
inline const char* drumVoiceName(int msb, int lsb, int pgm, int note)
{
    if (note < kDrumFirstNote || note > kDrumLastNote) return nullptr;
    for (int i = 0; i < kDrumKitCount; ++i)
    {
        const DrumKit& k = kDrumKits[i];
        if (k.msb == msb && k.lsb == lsb && k.pgm == pgm)
            return k.keys[note - kDrumFirstNote];
    }
    return nullptr;
}

